	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/iam/area-memberships/{user_id}/{area_code}", wrapper.RevokeAreaMembership)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/capabilities", wrapper.ListCapabilities)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/kpi", wrapper.GetKpi)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/presence/snapshot", wrapper.GetPresenceSnapshot)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/role-capabilities", wrapper.ListRoleCapabilities)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/roles", wrapper.ListRoles)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/usage", wrapper.GetUsage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/iam/users", wrapper.CreateManagedUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/iam/users/bulk", wrapper.BulkUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/iam/users/invite", wrapper.InviteUser)
